def audit(client, cid, campaign_id):
    queries = {k: v.replace("{campaign_id}", campaign_id) for k, v in QUERIES.items()}
    start = (datetime.now(timezone.utc) - timedelta(days=29)).strftime("%Y-%m-%d")
    end = datetime.now(timezone.utc).strftime("%Y-%m-%d %H:%M:%S")
    queries["change_history"] = (
        "SELECT change_event.change_date_time, change_event.change_resource_type, "
        "change_event.change_resource_name, change_event.client_type, change_event.user_email, "
        "change_event.old_resource, change_event.new_resource, change_event.changed_fields "
        "FROM change_event WHERE change_event.change_date_time >= '" + start
        + "' AND change_event.change_date_time <= '" + end
        + "' AND campaign.id = " + campaign_id
        + " ORDER BY change_event.change_date_time DESC LIMIT 10000"
    )
    out = {"customer_id": cid, "campaign_id": campaign_id,
           "captured_at": datetime.now(timezone.utc).isoformat(),
           "queries": queries, "data": {}, "errors": {}}
    for name, gaql in queries.items():
        try:
            out["data"][name] = query(client, cid, gaql)
        except Exception as error:
            # Never stringify auth/transport errors or dump config.
            if hasattr(error, "failure"):
                out["errors"][name] = {
                    "type": type(error).__name__, "request_id": error.request_id,
                    "codes": [str(e.error_code).strip() for e in error.failure.errors]}
            else:
                out["errors"][name] = {"type": type(error).__name__}
    out["complete"] = not out["errors"]
    out["change_history_may_be_truncated"] = len(out["data"].get("change_history", [])) >= 10000
    return out
